public static int findSmallestInteger(int n) {
    // Convert number to array of its digits
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Step 1: find the pivot index i such that digits[i] < digits[i+1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such pivot, n is the highest permutation of its digits
    if (i < 0) {
        return -1;
    }

    // Step 2: find the rightmost successor to the pivot that is greater than pivot
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Step 3: swap pivot with successor
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Step 4: reverse the suffix starting at i+1
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert back to integer
    long result = 0;
    for (char d : digits) {
        result = result * 10 + (d - '0');
        if (result > Integer.MAX_VALUE) {
            // If overflow would occur, return -1
            return -1;
        }
    }

    return (int) result;
}

